// Block (composition) — a form for writing a product review: a star score, a title and the review.
// Arranges only; composes Form/Rating/TextField/Textarea/Button/Alert/Stack. Posture: Panel (it sits
// under a product's reviews), so it takes the width it is given and its heading is a section label.
import type { FormEvent, Ref } from "react";
import { Form } from "../components/Form";
import { Rating } from "../components/Rating";
import { TextField } from "../components/TextField";
import { Textarea } from "../components/Textarea";
import { Button } from "../components/Button";
import { Alert } from "../components/Alert";
import { Stack } from "../layouts/Stack";
import "./ReviewForm.css";

export interface ReviewFormProps {
  /** Section heading above the fields. */
  heading?: string;
  /** Called with the score (1 to 5), the title and the review text. */
  onSubmit?: (review: { rating: number; title: string; body: string }) => void;
  /** Form-level error, shown above the fields. */
  errorMessage?: string;
  /** Puts the submit button in a pending state and blocks re-submit. */
  isPending?: boolean;
  className?: string;
  ref?: Ref<HTMLFormElement>;
}

export function ReviewForm({
  heading = "Write a review",
  onSubmit,
  errorMessage,
  isPending,
  className,
  ref,
}: ReviewFormProps) {
  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const data = new FormData(event.currentTarget);
    onSubmit?.({
      rating: Number(data.get("rating") ?? 0),
      title: String(data.get("title") ?? ""),
      body: String(data.get("body") ?? ""),
    });
  };

  return (
    <Form isPending={isPending} ref={ref} onSubmit={handleSubmit} className={className ? `sd-reviewform ${className}` : "sd-reviewform"}>
      <Stack gap="large" className="sd-reviewform__content">
        {heading && (
          <>
            <h2 className="sd-reviewform__heading sd-type-title-medium">{heading}</h2>
          </>
        )}
        {/* live="assertive": see `AlertProps.live` — submit failure is the case that earns it. */}
        {errorMessage && (
          <Alert variant="error" live="assertive">
            {errorMessage}
          </Alert>
        )}
        <Stack gap="medium" className="sd-reviewform__fields">
          <Rating label="Your rating" name="rating" isRequired />
          <TextField label="Title" name="title" isRequired />
          <Textarea label="Review" name="body" rows={5} isRequired />
        </Stack>
        <Button size="large" type="submit" variant="primary" isPending={isPending}>
          Submit review
        </Button>
      </Stack>
    </Form>
  );
}

/* ReviewForm.css — arrangement only; Component look stays with its owners. A Panel: no width of its
   own, the page decides it. */
.sd-reviewform__heading {
  margin: 0;
}
